import {
  basicCatalog,
  Catalog,
  createReactComponent,
  type ReactComponentImplementation,
} from "@copilotkit/a2ui-renderer";
import { TableCellValue } from "./table-cell-value";

function createTableCatalog() {
  const text = basicCatalog.components.get("Text")!;
  const DefaultText = text.render;
  const cellText = createReactComponent(
    text,
    ({ props, context, buildChild }) => {
      // Only decorate cells generated by Dingent, not headings or button labels.
      if (/^row_\d+_cell_\d+$/.test(context.componentModel.id)) {
        return (
          <div className="m-2 min-w-0">
            <TableCellValue value={props.text} />
          </div>
        );
      }
      return <DefaultText context={context} buildChild={buildChild} />;
    },
  );
  return new Catalog<ReactComponentImplementation>(
    basicCatalog.id,
    [...basicCatalog.components.values()].map((component) =>
      component.name === "Text" ? cellText : component,
    ),
    [...basicCatalog.functions.values()],
    basicCatalog.themeSchema,
  );
}

export const tableCatalog = createTableCatalog();
